function nav(){const q=($('#settings-search')?.value||'').trim().toLowerCase();let html='';const groups={};Object.entries(data).forEach(([id,p])=>{if(!groups[p.group])groups[p.group]=[];groups[p.group].push({id,...p})});groups['연결된 앱']=[{id:'apps',...data.apps},...Object.keys(state.connections).map(id=>({id:'source/'+id,...sourcePage(id),source:true}))];for(const [g,items] of Object.entries(groups)){const filtered=items.filter(x=>{if(!q)return true;const rows=(x.sections||[]).flatMap(s=>s.rows||[]).flat();return `${x.label} ${x.title} ${x.desc} ${rows.join(' ')}`.toLowerCase().includes(q)});if(!filtered.length)continue;html+=`<div class="nav-group">${esc(g)}</div>`;for(const x of filtered){const c=x.source?state.connections[x.id.slice(7)]:null;html+=`<button class="nav-item ${state.page===x.id?'active':''}" data-nav="${esc(x.id)}"><span class="nav-icon">${icons[x.icon||'plug']||'•'}</span>${c?`<span class="nav-dot ${c.status==='ok'?'ok':c.enabled?'warn':'off'}"></span>`:''}<span class="nav-label">${esc(x.label)}</span></button>`}}if(q&&!html)html='<div class="empty">일치하는 설정이 없습니다.</div>';$('#nav').innerHTML=html}
function sourcePage(id){const c=state.connections[id]||{type:id,name:id,status:'warn',access:false,enabled:true,items:0};const t=templates.find(x=>x[0]===c.type)||templates[0];return {group:'연결된 앱',label:c.name||t[1],icon:'plug',title:c.name||t[1],desc:`${t[3]} 연결의 기본 설정과 검색 범위를 관리합니다.`,notes:['연결 ID·인스턴스 ID·실행 환경은 고급 설정으로 접었습니다.','상태를 설치·AI 접근·검색 준비의 체크리스트로 바꿨습니다.'],sections:[]}}
function header(p){return `<div class="page-head"><div><h1>${esc(p.title)}</h1><p>${esc(p.desc)}</p></div><span class="save-state" id="save-state">✓ 자동 저장됨</span></div>${state.notes?`<div class="notes"><strong>변경 메모</strong><ul>${(p.notes||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}`}
function path(p){return state.notes&&p?`<span class="path">${esc(p)}</span>`:''}
function toggle(id,on=true){return `<button class="switch ${on?'on':''}" aria-label="${esc(id)}" data-toggle="${esc(id)}" aria-pressed="${on?'true':'false'}"></button>`}
function row(r){const [id,label,hint,type,value,p]=r;let control='';const on=value==='on'||(id==='access'&&value);if(type==='toggle')control=toggle(id,on);else if(type==='seg')control=`<div class="segmented">${value.split('|').map((v,i)=>`<button class="${(state.appearance==='light'?i===0:i===1)?'active':''}" data-seg="${v}">${v}</button>`).join('')}</div>`;else if(type==='select')control=`<select class="select compact" data-select="${esc(id)}">${value.split('|').map(v=>`<option>${esc(v)}</option>`).join('')}</select>`;else if(type==='number'||type==='text')control=`<input class="input ${type==='number'?'compact':''}" type="${type==='number'?'number':'text'}" placeholder="${esc(value)}" data-input="${esc(id)}">`;else if(type==='textarea')control=`<textarea class="textarea" data-input="${esc(id)}" placeholder="${esc(value)}"></textarea>`;else if(type==='chips')control=`<div class="chips">${value.split('|').map(v=>`<span class="chip">${esc(v)} <button aria-label="삭제">×</button></span>`).join('')}<button class="chip add" data-chip-add="${esc(id)}">+ 추가</button></div>`;else if(type==='info')control=`<span class="mini">${esc(value)}</span>`;return `<div class="row ${['chips','textarea'].includes(type)?'stack':''}" data-row="${esc(id)}" data-search="${esc(label+' '+hint+' '+(p||''))}"><div class="label">${esc(label)}${state.notes&&p?`<span class="proposal">매핑</span>`:''}<span class="hint">${esc(hint)}</span>${path(p)}</div><div class="control">${control}</div></div>`}
function section(s){if(s.custom)return `<section class="section"><h2 class="section-title">${esc(s.title)}</h2>${s.desc?`<p class="section-desc">${esc(s.desc)}</p>`:''}<div class="custom">${custom(s.custom)}</div></section>`;const body=(s.rows||[]).map(row).join('');return `<section class="section"><h2 class="section-title">${esc(s.title)}</h2>${s.desc?`<p class="section-desc">${esc(s.desc)}</p>`:''}${s.advanced?`<details class="details"><summary>${esc(s.title)} 보기</summary><div class="details-body card">${body}</div></details>`:`<div class="card">${body}</div>`}</section>`}
function custom(kind){if(kind==='privacy')return `<div class="card">${Object.entries(state.connections).map(([id,c])=>`<div class="row"><div class="label">${esc(c.name)}<span class="hint">${c.access?'AI 답변에 사용 중입니다.':'허용하기 전에는 AI가 이 앱을 읽지 않습니다.'}</span></div><div class="control">${c.access?'<span class="status ok">허용됨</span>':''}${toggle('access:'+id,c.access)}</div></div>`).join('')}</div>`;
if(kind==='ai')return `<div class="card"><div class="row stack"><div class="label">AI 서비스<span class="hint">자주 사용하는 서비스를 먼저 보여드립니다. 키는 운영체제의 안전한 저장소에 보관됩니다.</span></div><div class="control"><div class="provider-grid">${providers.map(x=>`<button class="provider ${x[0]==='openrouter'?'selected':''}" data-provider="${x[0]}"><b>${x[1]}</b><small>${x[2]} · 키 있음</small></button>`).join('')}</div></div></div><div class="row stack"><div class="label">모델<span class="hint">416개 모델 중 이름으로 검색할 수 있습니다.</span></div><div class="control"><div class="combo"><input class="combo-input" id="model-input" placeholder="모델 검색" value="${esc(state.modelQuery)}"><div class="combo-list" id="model-list">${models.filter(m=>m.toLowerCase().includes(state.modelQuery.toLowerCase())).map(m=>`<button class="combo-option" data-model="${esc(m)}"><span>${esc(m)}</span><small>${m.includes('Sonnet')||m.includes('GPT-5')?'추천':''}</small></button>`).join('')||'<span class="empty">검색 결과가 없습니다.</span>'}</div></div></div></div><div class="row"><div class="label">API 키<span class="hint">키를 입력하면 암호화하여 저장합니다. 다시 표시하지 않습니다.</span></div><div class="control"><span class="status ok">키 저장됨</span><button class="btn" data-action="test">연결 확인 <span class="proposal">제안</span></button></div></div></div>`;
if(kind==='quality')return `<div class="callout info"><strong>문서 내용은 이 컴퓨터에서 분석합니다.</strong><br>의미 검색을 위한 문서 분석 모델은 로컬에서 실행됩니다. 답변을 만들 때는 선택한 AI 서비스로 관련 문장 일부가 전송될 수 있습니다.</div><div class="card"><div class="row stack"><div class="label">문서 분석 모델<span class="hint">문서의 의미를 이해해 검색 결과를 넓혀줍니다.</span></div><div class="control"><div class="provider-grid"><button class="provider ${state.embed==='balanced'?'selected':''}" data-embed="balanced"><b>균형 · 권장</b><small>Qwen3 Embedding</small></button><button class="provider ${state.embed==='light'?'selected':''}" data-embed="light"><b>가벼움</b><small>EmbeddingGemma</small></button><button class="provider ${state.embed==='local'?'selected':''}" data-embed="local"><b>직접 연결</b><small>내 컴퓨터의 서버</small></button></div></div></div><div class="row"><div class="label">현재 색인 상태<span class="hint">마지막 분석: 오늘 09:42 · 문서 1,284개</span></div><div class="control"><button class="btn" data-action="reindex">다시 분석</button></div></div><div class="row"><div class="label">검색 결과 다듬기<span class="hint">가장 관련 있는 결과를 위로 정렬합니다. 외부 AI 서비스로 일부 검색 결과가 전송될 수 있습니다.</span></div><div class="control">${toggle('rerank',state.rerank)}</div></div>${state.rerank?`<div class="row"><div class="label">정렬 모델<span class="hint">OpenRouter 키가 필요합니다.</span></div><div class="control"><select class="select compact"><option>voyageai / rerank-3-lite</option><option>cohere / rerank-v3.5</option></select></div></div>`:''}</div>`;
if(kind==='folders')return `<div class="card"><div class="row stack"><div class="label">포함할 폴더<span class="hint">Dazzi가 읽고 검색할 폴더입니다.</span></div><div class="control"><div class="folder-list"><div class="folder"><span>⌂ ~/Documents</span><button class="link-btn">삭제</button></div><div class="folder"><span>⌂ ~/Desktop/업무</span><button class="link-btn">삭제</button></div><button class="btn" data-action="folder">+ 폴더 추가 <span class="proposal">제안</span></button></div></div></div></div>`;
if(kind==='excludes')return `<div class="card"><div class="row stack"><div class="label">제외할 폴더와 파일<span class="hint">검색하지 않을 경로를 추가합니다.</span></div><div class="control"><div class="chips"><span class="chip">node_modules ×</span><span class="chip">.git ×</span><span class="chip">dist ×</span><button class="chip add">+ 항목 추가</button></div></div></div></div>`;
if(kind==='sources')return `<div>${Object.entries(state.connections).map(([id,c])=>sourceCard(id,c)).join('')}</div>`;
if(kind==='gallery')return `<div>${['메신저','문서·노트','메일','파일·클라우드','개발·기타'].map(cat=>`<div class="section"><h3 class="section-title">${cat}</h3><div class="gallery">${templates.filter(t=>t[2]===cat).map(t=>`<button class="gallery-card" data-add="${t[0]}"><span class="app-icon" style="background:${t[5]}">${t[4]}</span><b>${t[1]}</b><p>${t[3]}</p></button>`).join('')}</div></div>`).join('')}</div>`;
if(kind==='advancedNotice')return `<div class="callout warn"><strong>대부분의 사용자는 바꿀 필요가 없습니다.</strong><br>잘못된 값은 검색 속도나 색인 동작에 영향을 줄 수 있습니다. 지원 안내를 받은 경우에만 수정하세요.</div>`;return ''}
function sourceCard(id,c){const t=templates.find(x=>x[0]===c.type)||templates[0];return `<button class="source-card" data-nav="source/${id}"><div class="source-top"><span class="app-icon" style="background:${t[5]}">${t[4]}</span><div><div class="source-title">${esc(c.name)}</div><div class="source-meta">${esc(t[3])} · ${c.items?c.items.toLocaleString()+'개 문서':'준비 필요'}</div></div><span class="status ${c.status==='ok'?'ok':'warn'}">${c.status==='ok'?'정상':'준비 필요'}</span><span class="source-chevron">›</span></div></button>`}
function sourceContent(id){const c=state.connections[id]||{type:id,name:id,status:'warn',access:false,enabled:true,items:0};const t=templates.find(x=>x[0]===c.type)||templates[0];const basic=[];if(c.type==='slack')basic.push(['workspace','워크스페이스 ID','Slack 주소에 있는 T로 시작하는 ID입니다.','text','예: T0435JHH63Z','datasources.'+id+'.connector.workspace']);if(c.type==='kakao')basic.push(['chatrooms','검색할 채팅방','비워두면 모든 채팅방을 검색합니다.','chips','전체','datasources.'+id+'.channels.names']);if(c.type==='cloud-drive')basic.push(['provider','클라우드 서비스','Google Drive, OneDrive 등 사용 중인 서비스입니다.','select','Google Drive|OneDrive|Dropbox|Box','datasources.'+id+'.connector.provider'],['remote','원격 이름','클라우드 드라이브 설정에 등록된 이름입니다.','text','예: my-drive','datasources.'+id+'.connector.remote'],['ext','가져올 파일 종류','비워두면 지원하는 문서를 모두 가져옵니다.','chips','.pdf|.docx|.md','datasources.'+id+'.connector.extensions']);if(c.type==='spotlight')basic.push(['onlyin','검색할 폴더','비워두면 Mac 전체를 검색합니다.','text','예: ~/Documents','datasources.'+id+'.connector.onlyIn']);return `<div class="page-head"><div><h1>${esc(c.name)}</h1><p>${esc(t[3])} · 변경 사항은 자동으로 저장됩니다.</p></div><span class="save-state">✓ 자동 저장됨</span></div>${state.notes?`<div class="notes"><strong>변경 메모</strong><ul><li>내부 연결 ID와 도구 이름을 기본 화면에서 숨겼습니다.</li><li>설치·AI 접근·검색 준비를 체크리스트로 바꿨습니다.</li></ul></div>`:''}<section class="section"><h2 class="section-title">연결 상태</h2><div class="card"><div class="row"><div class="label">사용 여부<span class="hint">끄면 이 연결을 검색에서 잠시 제외합니다.</span></div><div class="control">${toggle('source-enabled:'+id,c.enabled)}</div></div><div class="row"><div class="label">도우미 프로그램<span class="hint">${t[0]==='spotlight'?'Mac에 기본으로 포함되어 있습니다.':`이 앱의 내용을 가져오려면 ${t[1]} 연결 도구가 필요합니다.`}</span></div><div class="control"><span class="status ${t[0]==='spotlight'?'ok':'warn'}">${t[0]==='spotlight'?'준비됨':'설치 필요'}</span><button class="btn">설치 방법 보기 <span class="proposal">제안</span></button></div></div><div class="row"><div class="label">AI 검색 허용<span class="hint">허용하면 AI 답변이 이 연결의 내용을 참고할 수 있습니다. 비슷한 분류의 연결에도 영향을 줄 수 있습니다.</span></div><div class="control">${c.access?'<span class="status ok">허용됨</span>':''}${toggle('source-access:'+id,c.access)}</div></div><div class="row"><div class="label">검색 준비<span class="hint">${c.items?`문서 ${c.items.toLocaleString()}개 · 오늘 09:42에 업데이트`:'아직 가져온 내용이 없습니다.'}</span></div><div class="control"><button class="btn" data-action="sync">지금 동기화 <span class="proposal">제안</span></button></div></div></div></section><section class="section"><h2 class="section-title">기본 설정</h2><div class="card">${row(['name','연결 이름','왼쪽 목록에 표시할 이름입니다.','text',c.name,'datasources.'+id])}${row(['desc','AI에게 알려줄 설명','이 연결을 언제 참고하면 좋은지 적어주세요.','textarea','예: 우리 팀의 업무 대화와 공지입니다.','datasources.'+id+'.description'])}${basic.map(row).join('')}${row(['poll','동기화 주기','새로운 내용을 확인하는 간격입니다.','select','5분|15분|30분|1시간|6시간|하루|수동','datasources.'+id+'.pollingIntervalMs'])}</div></section><section class="section"><h2 class="section-title">고급 설정</h2><details class="details"><summary>연결 ID·실행 환경 보기</summary><div class="details-body card">${row(['alias','연결 ID','설정 파일에서 이 연결을 구분하는 이름입니다.','text',id,'datasources.'+id])}${row(['instance','인스턴스 ID','소스 경로·컬렉션에 사용하는 내부 값입니다.','text','기본값','datasources.'+id+'.instanceId'])}${row(['tags','분류 태그','AI 접근 권한을 연결하는 분류입니다.','chips','문서|개인정보','datasources.'+id+'.tags'])}${row(['timeout','검색 시간 제한','연결 도구를 기다리는 최대 시간입니다.','number','기본값 (초)','datasources.'+id+'.connector.timeoutMs'])}${row(['env','실행 환경 변수','비밀번호나 토큰은 이곳에 직접 넣지 마세요.','textarea','KEY=value','datasources.'+id+'.connector.env'])}</div></details></section><div class="danger"><h3>연결 해제</h3><p>Dazzi의 검색 설정에서만 이 연결을 제거합니다. 원본 앱의 데이터는 삭제하지 않습니다.</p><button class="btn danger" data-action="delete">연결 삭제</button></div>`}
function render(){nav();const main=$('#content');if(state.page.startsWith('source/')){main.innerHTML=`<div class="content-inner">${sourceContent(state.page.slice(7))}</div>`;return}const p=data[state.page]||data.general;main.innerHTML=`<div class="content-inner">${header(p)}${p.sections.map(section).join('')}</div>`;if(state.page==='ai')$('#model-list')?.classList.add('visible')}
function save(msg='변경 사항이 저장되었습니다.'){const el=$('#save-state');if(el){el.textContent='저장 중…';el.classList.add('saving')}setTimeout(()=>{if(el){el.textContent='✓ 자동 저장됨';el.classList.remove('saving')}toast(msg)},350)}
let toastTimer;function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1800)}
function openModal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog">${html}</div></div>`}
function addFlow(type){const t=templates.find(x=>x[0]===type);openModal(`<h2>${esc(t[1])} 연결</h2><p>${esc(t[3])} 연결 이름을 정하고 기본 설정을 시작합니다.</p><label class="label">연결 이름<span class="hint">왼쪽 목록에 표시될 이름입니다.</span><input class="input" id="new-name" value="${esc(t[1])}"></label><div class="callout info" style="margin-top:14px"><strong>연결 후에도 설정은 자동으로 저장됩니다.</strong><br>세부 실행 환경은 고급 설정에서 확인할 수 있습니다.</div><div class="modal-actions"><button class="btn" data-close-modal>취소</button><button class="btn primary" data-connect="${type}">연결 추가</button></div>`)}
document.addEventListener('click',e=>{const navEl=e.target.closest('[data-nav]');if(navEl){state.page=navEl.dataset.nav;history.replaceState(null,'','#'+state.page);render();return}if(e.target.closest('#theme-toggle')){state.appearance=state.appearance==='light'?'dark':'light';document.documentElement.dataset.appearance=state.appearance;$('#theme-toggle').textContent=state.appearance==='dark'?'라이트 모드':'다크 모드';save('화면 모드가 변경되었습니다.');return}if(e.target.closest('#notes-toggle')){state.notes=!state.notes;document.body.classList.toggle('show-notes',state.notes);e.target.closest('#notes-toggle').classList.toggle('active',state.notes);render();return}const tog=e.target.closest('[data-toggle]');if(tog){const id=tog.dataset.toggle;if(id==='rerank'){state.rerank=!state.rerank;render();save();return}if(id==='access:'+id.slice(7)){const k=id.slice(7);state.connections[k].access=!state.connections[k].access;render();save();return}if(id.startsWith('source-access:')){const k=id.slice(14);state.connections[k].access=!state.connections[k].access;render();save();return}if(id.startsWith('source-enabled:')){const k=id.slice(15);state.connections[k].enabled=!state.connections[k].enabled;render();save();return}save();return}const seg=e.target.closest('[data-seg]');if(seg){state.appearance=seg.dataset.seg==='라이트'?'light':'dark';document.documentElement.dataset.appearance=state.appearance;render();save('화면 모드가 변경되었습니다.');return}const emb=e.target.closest('[data-embed]');if(emb&&emb.dataset.embed!==state.embed){openModal(`<h2>문서 전체를 다시 분석할까요?</h2><p>문서 이해 모델을 바꾸면 기존 검색 색인을 새 모델로 다시 만들어야 합니다. 문서 수에 따라 시간이 걸릴 수 있습니다.</p><div class="modal-actions"><button class="btn" data-close-modal>취소</button><button class="btn primary" data-confirm-embed="${emb.dataset.embed}">변경하고 다시 분석</button></div>`);return}const model=e.target.closest('[data-model]');if(model){state.modelQuery=model.dataset.model;state.modelOpen=false;render();save('모델이 선택되었습니다.');return}const add=e.target.closest('[data-add]');if(add){addFlow(add.dataset.add);return}const connect=e.target.closest('[data-connect]');if(connect){const t=templates.find(x=>x[0]===connect.dataset.connect);const id=connect.dataset.connect+'-'+Date.now().toString().slice(-4);state.connections[id]={type:t[0],name:$('#new-name').value||t[1],status:'warn',access:false,enabled:true,items:0};$('#modal-root').innerHTML='';state.page='source/'+id;history.replaceState(null,'','#'+state.page);render();toast('연결이 추가되었습니다.');return}if(e.target.closest('[data-confirm-embed]')){state.embed=e.target.closest('[data-confirm-embed]').dataset.confirmEmbed;$('#modal-root').innerHTML='';render();toast('모델을 바꾸고 문서를 다시 분석합니다.');return}if(e.target.closest('[data-action="test"]')){toast('연결 확인 결과: 정상입니다.');return}if(e.target.closest('[data-action="reindex"]')){toast('문서 다시 분석을 시작했습니다.');return}if(e.target.closest('[data-action="folder"]')){toast('폴더 선택기는 실제 구현에서 Finder 창으로 연결됩니다.');return}if(e.target.closest('[data-action="sync"]')){toast('동기화를 시작했습니다.');return}if(e.target.closest('[data-action="delete"]')){const id=state.page.slice(7);if(confirm('이 연결을 삭제할까요? 원본 앱의 데이터는 삭제되지 않습니다.')){delete state.connections[id];state.page='apps';history.replaceState(null,'','#apps');render();toast('연결이 삭제되었습니다.')}return}if(e.target.closest('[data-close-modal]')&&e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML='';if(e.target.closest('[data-chip-add]'))toast('목록 입력 UI는 실제 구현에서 항목 추가 창으로 연결됩니다.')});
document.addEventListener('input',e=>{if(e.target.id==='settings-search'){render();return}if(e.target.id==='model-input'){state.modelQuery=e.target.value;const list=$('#model-list');if(list)list.innerHTML=models.filter(m=>m.toLowerCase().includes(state.modelQuery.toLowerCase())).map(m=>`<button class="combo-option" data-model="${esc(m)}"><span>${esc(m)}</span><small>${m.includes('Sonnet')||m.includes('GPT-5')?'추천':''}</small></button>`).join('')||'<span class="empty">검색 결과가 없습니다.</span>'}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1)||'general';state.page=h;render()});state.page=location.hash.slice(1)||'general';document.documentElement.dataset.appearance=state.appearance;render();